  Activity_119693_ActivityTips = {
    Text = "<Title:Правила события>\n·Во время события каждый Страж, совершивший суммарно 200 использований Жетонов ключа, может выбрать и пробудить 1 из 8 лимитированных SSR-пробуждённых, включая Расплавленную·Доль, Клементину, Крепюсант, Кастора, Дюлесейна, Кэтигулу, Пикмана и Поллукса.\n·Если Страж выберет уже пробуждённого персонажа: при получении того же SSR-пробуждённого со 2-го по 16-й раз каждый раз он будет конвертирован в 1 осколок соответствующего пробуждённого и «Осадок Истока» × 50; начиная с 17-го раза лимитированный SSR-пробуждённый будет конвертирован в «Очищенный осколок духовного ядра» × 2, «Осколок духовного ядра» × 6 и «Осадок Истока» × 250."
