  Activity_124801_ActivityPlot = {
    Text = "«Я хочу, чтобы все люди играли в Всевозможную карту!»\nГость из другого пространства-времени из-за случайности попал в пространство фазового поединка и изменил его до неузнаваемости.\nЧтобы обратить пространство вспять, Хранители тайн из разных времён выберут сильнейшего и бросят вызов этому гостю."
