  Activity_127173_ActivityTips = {
    Text = "<Title:Правила события>\n·Во время события «Художник» Страж может использовать системный предустановленный Отряд с Пикманом для неограниченного прохождения указанных этапов.\n·Во время прохождения этапов события невозможно изменять Пробуждённых в отряде.\n<Title:Награды события>\n·После первого выполнения испытания этапа можно получить пробные награды в интерфейсе события."
