  Activity_130175_ActivityPlot = {
    Text = "Мир слишком одинок, мир слишком пустынен — Прислушайся же, станьте свидетелями.\nИстерзанная плоть в долгом безмолвии ждёт, ждёт, когда одуванчик расцветёт в пустыне.\nА затем она будет наполнена сияющей любовью и вновь обретёт новую жизнь."
