  Activity_131849_ActivityTips = {
    Text = "<Title: Вечная память>\n·Данные лимитированные Хроники содержат 8 наборов. Первый набор можно получить бесплатно, наборы 2–8 доступны только после покупки «Вечной памяти».\n·После покупки «Вечной памяти» можно сразу получить награду 2-го набора; последующие наборы станут доступны через определённое время.\n·При покупке «Вечной памяти» до 30 мая 9:00 вы дополнительно получите: эксклюзивный аватар «Весёлая охота» и «Приглашение Незримого» ×10! После 30 мая 9:00 лимитированные эксклюзивные награды больше не будут доступны.\n·Покупка «Вечной памяти» ограничена по времени — после истечения срока покупка станет невозможной. Просим Хранителей тайн приобрести до 29 июня 9:00."
