  Activity_139591_ActivityName = {
    Text = "«Благодарность» кота"
  },
  Activity_139591_ActivityPlot = {
    Text = "«Срочное уведомление! Всем учащимся и преподавателям немедленно прекратить текущую работу и помочь в поимке сбежавших подопытных.»\n«Повторяю, всем учащимся и преподавателям немедленно прекратить текущую работу и помочь в поимке сбежавших… Чёрт! Эти коты уже здесь!»\nКогда вы услышали панический голос из громкоговорителя, весь кампус уже был затоплен чёрным мехом, и все в суматохе ловили этих маленьких негодников, сбежавших из лаборатории.\nПохоже, в отместку за праздник Моления о годе, эти чёрные коты медленно и организованно стекаются к вашему общежитию.\nВпрочем… учитывая огромное количество золотых купонов и серебряных ядер, которые они несут с собой, сложно сказать — они пришли мстить или «отблагодарить».\nВнимание, не переусердствуйте с ловлей."
  },
  Activity_139591_ActivityStageEndContent = {
    Text = "Мероприятие завершено"
  },
  Activity_139591_ActivityTips = {
    Text = "<Title: «Благодарность» кота>\n·«Благодарность» кота содержит 7 невоспроизводимых этапов с прямым вызовом. Каждый день открывается 1 этап.\n·После победы над соответствующим «Мерным чёрным котом» в каждом испытании накапливается прогресс задания, и в «Журнале поимки чёрных котов» можно получить соответствующие награды.\n·Каждый «Мерный чёрный кот» имеет множество копий. Во время события можно участвовать в испытаниях неограниченное количество раз, поддерживается автобой.\n·На каждом этапе предоставляются различные артефакты, дающие мощные бонусы.\n·На всех этапах необходимо выбирать помощника. За всё событие каждый взаимно подписанный Страж может оказать вам помощь только один раз.\n\n<Title: Компенсация уровня>\n·В «Благодарности» кота действует механизм компенсации уровня, чтобы все Хранители тайн могли сражаться плечом к плечу!\nПравила компенсации уровня:\n  ·В отряде расследования Пробуждённые с уровнем ниже 60 будут повышены до 60 уровня на время испытания.\n  ·В отряде расследования Пробуждённые с уровнем навыков ниже 5 будут повышены до 5 уровня навыков на время испытания.\n  ·В отряде расследования Пробуждённые с уровнем «Предвестия безумия» ниже 6 будут повышены до 6 уровня на время испытания.\n  ·В отряде расследования Пробуждённые с уровнем «Духопластической совместимости» ниже 5 будут повышены до 5 уровня на время испытания.\n  ·Если Уровень Хранителя тайн ниже 60, на время испытания он будет повышен до 60.\n\n<Title:Журнал поимки чёрных котов>\n·Во время события, после победы над соответствующим «Мерным чёрным котом», Страж может накапливать прогресс задания и получать награды в «Журнале поимки чёрных котов». Журнал делится на «Личный журнал поимки» и «Журнал поимки Кампуса». «Личный журнал поимки» — это индивидуальные задания Хранителя тайн. «Журнал поимки Кампуса» — задания для всех Хранителей тайн Кампуса.\n\n<Title:Рейтинг поимки>\n·Во время события Страж может просматривать «Рейтинг по количеству поимок» и «Рейтинг по количеству помощи» в разделе «Рейтинг поимки».\n\n<Title:Время события>\n· До 15 июня 9:00 (GMT+8) Хранители тайн могут войти на страницу события и принять участие. После этого времени новые Хранители тайн не смогут присоединиться к испытанию. Если событие ещё не завершено, уже участвующие Хранители тайн могут продолжать испытания.\n·Если «Общее количество поимок» будет достигнуто до 15 июня 9:00 (GMT+8), событие завершится 29 июня 9:00 (GMT+8). Если «Общее количество поимок» не будет достигнуто до 15 июня 9:00 (GMT+8), событие завершится через 14 дней после достижения «Общего количества поимок»."
  },
