  Activity_24194_ActivityName = {
    Text = "Красная Леди"
  },
  Activity_24194_ActivityTips = {
    Text = "<Title:Правила события>\n·В период проведения события «Красная Леди» Страж может использовать системный предустановленный Отряд с Сорель и неограниченное количество раз проходить указанные этапы.\n·Во время прохождения этапов события невозможно изменять Пробуждённых в отряде.\n<Title:Награды события>\n·После первого выполнения испытания этапа можно получить пробные награды в интерфейсе события."
  },
  Activity_24195_ActivityName = {
    Text = "Цветок из ила"
  },
  Activity_24195_ActivityTips = {
    Text = "<Title:Правила события>\n·В период проведения события «Цветок из ила» Страж может использовать системный предустановленный Отряд с Лили и неограниченное количество раз проходить указанные этапы.\n·Во время прохождения этапов события невозможно изменять Пробуждённых в отряде.\n<Title:Награды события>\n·После первого выполнения испытания этапа можно получить пробные награды в интерфейсе события."
  },
  Activity_24992_ActivityName = {
    Text = "Академический Подарок"
  },
  Activity_24992_ActivityTips = {
    Text = "Правила события:\n1, После ежедневного входа в игру Страж может получить награду за Вход в разделе «Школьные дары».\n2, Награды разблокируются последовательно в зависимости от общего числа дней входа Хранителя тайн. Ежедневная награда за Вход обновляется в 9:00(GMT+8)."
  },
  Activity_25011_ActivityName = {
    Text = "На расстоянии шага"
  },
  Activity_25011_ActivityPlot = {
    Text = "Ты делаешь шаг вперёд и попадаешь в иное пространство-время."
  },
  Activity_25011_ActivityTips = {
    Text = "<Title:Условия участия>\n·Доступно после прохождения погружения в сознание «Желание рыцаря» в обычном режиме. \n<Title:Расследования>\n·Во время события каждый день открывается новое расследование в «На расстоянии шага». Страж может разблокировать и начать расследование без затрат ресурсов. За выполнение расследований можно получить Безупречное ядро, Знаки расследования, опыт Хранителя тайн и другие награды.\n·После завершения события прогресс расследований «На расстоянии шага» сохранится. Страж сможет в погружении в сознание потратить Жемчужины разложения для разблокировки незавершённых расследований и получить те же награды, что и во время события.<Title:Ограниченные награды>\n·Во время события доступны ограниченные награды. После прохождения «На расстоянии шага» в обычном режиме и выполнения расследований Страж может получить Счастливые конфеты и Серебряные ядра! Ограниченные награды доступны только во время события, после его завершения их нельзя будет получить."
  },
  Activity_25011_UnlockConditionExplanation = {
    Text = "Разблокируется после прохождения погружения в сознание «Желание рыцаря»"
  },
  Activity_25012_ActivityName = {
    Text = "Воспевание розы"
  },
  Activity_25012_ActivityPlot = {
    Text = "Дамы и господа.\nНежная ночь уже окутала нас, приготовьте благородное Прекрасное Прекрасное вино.\nЭто длинная история, позвольте нам рассказать её неторопливо.."
  },
  Activity_25012_ActivityTips = {
    Text = "<Title:Условия участия>\n·После завершения «Расследовательской операции» 2-9 на обычном уровне можно участвовать.\n<Title:События расследования>\n·Во время акции каждый день будет открываться новое расследование из «Воспевания розы», Страж может разблокировать расследование без расхода ресурсов. После завершения расследования можно получить Чистое ядро, Значок следователя и опыт Хранителя тайн как награду за расследование.\n·После завершения акции расследование в «Воспевании розы» прогрессирует, Страж сможет разблокировать не разблокированные расследования, потратив жемчужины эрозии в Оперативной записи. Завершив незаконченные расследования после окончания акции, также можно получить такую же награду за расследование, как и во время проведения акции.<Title:Ограниченное предложение награды>\n·Во время акции будут доступны ограниченные награды. Хранители тайн, прошедшие обычный режим «Воспевания розы» и завершившие расследование событий в «Воспевании розы», смогут получить Чистое ядро, Философский камень и Серебро как награду! Ограниченные награды доступны только во время проведения акции, после её завершения их нельзя будет выполнить или получить."
  },
  Activity_25012_UnlockConditionExplanation = {
    Text = "После завершения миссии «Расследовательская операция»2-9·Обычный будет разблокировано"
  },
  Activity_34754_ActivityName = {
    Text = "Магия историй"
  },
  Activity_34754_ActivityTips = {
    Text = "<Title:Условия участия>\n·После завершения миссии «Расследовательская операция» 2-9 на обычном уровне можно участвовать.\n<Title:Расследования>\n·В течение акции каждый день будет представлено новое расследование из «Магии истории», которое можно разблокировать и завершить без расхода ресурсов. После завершения расследования можно получить Чистое ядро, Значок следователя и Опыт Хранителя, а также другие награды за расследование.\n·После окончания акции прогресс расследования в «Магии истории» сохранится, и хранитель тайн сможет разблокировать незавершенные расследования, потратив жемчужины эрозии. Завершив незавершенные расследования, также можно получить те же награды за расследование, что и во время акции.\n<Title:Ограниченное предложение награды>\n·В рамках акции предлагаются временные бонусы. Страж, завершивший обычный режим «Магии истории» и расследования, может получить Чистое ядро, Философский камень и Серебро в качестве наград! Ограниченные награды доступны только во время акции, после ее окончания завершить и получить их будет невозможно."
  },
  Activity_34755_ActivityName = {
    Text = "Магия историй"
  },
  Activity_34755_ActivityTips = {
    Text = "<Title:Описание мероприятия>\n·Во время мероприятия временно доступен режим «Спланированная тайна», а «Особая операция: Магия историй» открыта для бесплатного разблокирования!\n\n<Title:Спланированная тайна>\n·«Спланированная тайна» включает 9 уровней сложности, рекомендуемый Уровень от 30 до 70, после прохождения уровней более низкой сложности открываются Уровни более высокой сложности.\n·Каждое испытание требует 60 единиц Линфеина, после каждого прохождения можно получить валюту мероприятия «Путешествующее вдохновение». Чем выше Сложный уровня, тем больше «Путешествующего вдохновения» можно получить!\n·«Путешествующее вдохновение» можно обменять на множество материалов для развития Пробуждённых в «магазине сценариев магии», а также на ограниченный SR колесо судьбы «35-миллиметровая магия», которое может быть повторно выпущено или добавлено в постоянное пробуждение в будущем.\n·При каждом испытании, кроме лидера, враги, события и карты могут изменяться, а также больше артефактов может появиться на уровне!\n·В «Сценарном мифе» можно использовать помощь ассоциации выпускников. \n\n<Title:Резонанс и достижения>\n·Расходуя «сердце исполнения», активируйте «Резонанс: Код режиссера», чтобы сделать Хранителя тайн сильнее в «Сценарном мифе», облегчая прохождение.\n·Хранители могут получать «сердце исполнения», достигая достижений мероприятия, кроме того, за достижения мероприятия можно получить ограниченный аватар «Во имя Серебряного Ключа: Лили»!\n\n<Title:Особая операция>\n·Во время мероприятия каждый день будет запускаться новое исследовательское событие из «Магии истории», Хранителям не нужно тратить ресурсы для разблокировки и проведения расследования, после завершения расследовательского события можно получить Чистое ядро, Значок следователя и опыт Хранителя тайн и другие награды.\n·После завершения мероприятия прогресс расследования «Магии истории» будет сохранен, Хранители могут использовать жемчужину эрозии в оперативной записи для разблокировки незаблокированных расследований, после завершения незавершенных расследований во время мероприятия также можно получить такие же награды, как и во время мероприятия.\n·В течение мероприятия будут предложены временные награды за достижения, Хранители, проходя обычный режим «Магии истории» и завершая расследовательские события «Магии истории», могут получить награду в виде сердечника из серебра в достижениях мероприятия! Награды за достижения доступны только в течение мероприятия, после завершения мероприятия их нельзя будет получить и завершить.\n"
  },
