    Text = "Это простой и счастливый день Ауретты — такой же, как каждый её день."
  },
  Activity_36841_ActivityTips = {
    Text = "<Title:Условия участия>\n·Доступно после прохождения погружения в сознание «Желание рыцаря» в обычном режиме. \n<Title:Расследования>\n·Во время события Страж может разблокировать и начать расследование без затрат ресурсов. За выполнение расследований можно получить Безупречное ядро, Знаки расследования, опыт Хранителя тайн и другие награды.\n·После завершения события прогресс расследований «Всё как обычно» сохранится. Страж сможет в погружении в сознание потратить Жемчужины разложения для разблокировки незавершённых расследований и получить те же награды, что и во время события.<Title:Ограниченные награды>\n·Во время события доступны ограниченные награды. После прохождения «Всё как обычно» в обычном режиме и выполнения расследований Страж может получить Чёрные застёжки и Серебряные ядра! Ограниченные награды доступны только во время события, после его завершения их нельзя будет получить."
  },
  Activity_36841_UnlockConditionExplanation = {
    Text = "Разблокируется после прохождения погружения в сознание «Желание рыцаря»"
  },
  Activity_36885_ActivityName = {
    Text = "Пламенное пиршество"
