  Activity_38716_ActivityTips = {
    Text = "<Title:Описание активности>\n·Страж может получить награду «Припасы перезапуска» непосредственно в разделе «Награда за возвращение».\n·Выполняя указанные тренировочные задания, можно получить награды в активности «Перезапуск расследования».\n·За выполнение всех тренировочных заданий можно получить дополнительную награду."
