  Activity_38717_ActivityTips = {
    Text = "<Title:Описание активности>\n·Страж может ежедневно после входа в игру получать награду за ежедневную отметку в «Возвращении в школу».\n·Награды разблокируются последовательно в зависимости от общего количества дней входа. Ежедневная награда за отметку обновляется в 9:00 (GMT+8)."
