  Activity_41378_ActivityTips = {
    Text = "Правила события:\n1, После выполнения указанных заданий Страж может получить награды в разделе «Подготовка к бедствию».\n2, «Подготовка к бедствию» доступна на постоянной основе.\n3, После разблокировки «Улучшенных хроник» за выполнение заданий можно получить дополнительные награды.\n4, Обратите внимание: «Улучшенные хроники», разблокированные в данном событии, действуют только в рамках этого события. Просим Хранителей тайн подходить к покупкам обдуманно."
