  Activity_45664_ActivityTips = {
    Text = "<Title:Условия участия>\n·Доступно после прохождения обычного режима погружения в сознание «Желание рыцаря». \n<Title:Расследования>\n·Во время события Хранители тайн могут разблокировать и проводить расследования без затрат ресурсов. За выполнение расследований можно получить награды: Безупречные ядра, Значки расследования и опыт Хранителя тайн.\n·После завершения события статус разблокировки и прогресс расследований «Падение великана» сохранятся. За завершение незаконченных расследований можно будет получить те же награды, что и во время события. Если расследование не было разблокировано во время события, после его окончания разблокировка будет стоить Начальные точки реальности ×3.<Title:Ограниченные по времени награды>\n·Во время события доступны ограниченные по времени награды. После прохождения обычного режима «Падение великана» и выполнения расследований «Падение великана» можно получить Кристаллы измерений и Серебряные ядра! Ограниченные по времени награды доступны только во время события — после его окончания их нельзя будет выполнить и получить."
  },
