  Activity_46609_ActivityPlot = {
    Text = "Истерия, также известная как истерика, истерия. \n В ваше время она была синонимом смерти. \n\n К счастью, ученые и следователи Мисаг были так же сумасшественны: они были полны решимости преодолеть эту проблему."
