  Activity_48826_ActivityTips = {
    Text = "<Title:Описание>\nЭто стихотворение, посвящённое игрокам, — об идеалах, о вере, о времени, проведённом вместе. Пусть искреннее сердце никогда не перестанет биться, пусть Серебряный ключ указывает путь.\n\n<Title:Правила события>\n·Во время события Страж может ежедневно после входа в игру получать памятное лимитированное SSR Колесо Судьбы «Полярная ночь и рассвет» в разделе «Полярная ночь и рассвет», всего 16 раз.\n·Награды разблокируются последовательно в зависимости от общего количества дней входа. Ежедневная награда за Вход обновляется в 9:00 (GMT+8)."
