  Activity_51611_ActivityTips = {
    Text = "<Title:Условия участия>\n·После завершения миссии «Расследовательская операция» 2-9 на обычном уровне можно участвовать.\n<Title:Расследования>\n·В течение акции каждый день будет представлено новое расследование из «Магии истории», которое можно разблокировать и завершить без расхода ресурсов. После завершения расследования можно получить Чистое ядро, Значок следователя и Опыт Хранителя, а также другие награды за расследование.\n·После окончания акции прогресс расследования в «Магии истории» сохранится, и хранитель тайн сможет разблокировать незавершенные расследования, потратив жемчужины эрозии. Завершив незавершенные расследования, также можно получить те же награды за расследование, что и во время акции.\n<Title:Ограниченное предложение награды>\n·В рамках акции предлагаются временные бонусы. Страж, завершивший обычный режим «Магии истории» и расследования, может получить Чистое ядро, Философский камень и Серебро в качестве наград! Ограниченные награды доступны только во время акции, после ее окончания завершить и получить их будет невозможно."
  },
  Activity_51888_ActivityName = {
    Text = "Осквернение"
