  Activity_51905_ActivityName = {
    Text = "Академический Подарок"
  },
  Activity_51905_ActivityTips = {
    Text = "Правила события:\n1, После ежедневного входа в игру Страж может получить награду за Вход в разделе «Школьные дары».\n2, Награды разблокируются последовательно в зависимости от общего числа дней входа Хранителя тайн. Ежедневная награда за Вход обновляется в 9:00(GMT+8)."
