  Activity_53727_ActivityTips = {
    Text = "<Title:Описание активности>\n·Задания «Дня возвращения» разделены на 4 группы, которые разблокируются на 1–й, 2–й, 3–й и 4–й день активности соответственно.\n·Страж может получить «Приглашение на возвращение», выполняя задания «Дня возвращения».\n·«Приглашения на возвращение» можно обменять на щедрые награды в «Магазине возвращения»."
