  Activity_53728_ActivityName = {
    Text = "Помощь в новом пути"
  },
  Activity_53728_ActivityTips = {
    Text = "<Title:Описание активности>\n·Во время активности «Помощь в новом пути» после прохождения Хранителем тайн «Закалки препаратов», «Мутного остаточного образа», «Глубинного остаточного образа», «Органического остаточного образа», «Мерного остаточного образа», «Хаотического скопления», «Руин Понапе», «Обители червей» и «Горловины Шварцшильда» награды в виде «Розовых золотых купонов» и материалов будут удвоены — до 6 раз в день.\n·Неиспользованные за день попытки удвоения награды сгорают на следующий день в 9:00 (GMT+8). Не забывайте использовать их вовремя~"
  },
