  Activity_56428_ActivityPlot = {
    Text = "В отражении глубокого моря сновидение короля рассеивается, и царство божеств уже в гниении.\nОна приходит из былых грез, вступая в руины обрушенного будущего.\nОна вопрошает абисс, но абисс хранит молчание.\nОна приносит Жертвенный ритуал абиссу, и ответь ей — только её."
