  Activity_61156_ActivityName = {
    Text = "Архивы финала"
  },
  Activity_61156_ActivityTips = {
    Text = "Правила события:\n1, После выполнения указанных заданий хроник Страж может получить награды в разделе «Хроники Конца».\n2, «Хроники Конца» доступны на постоянной основе.\n3, После разблокировки «Улучшенных хроник» за выполнение заданий можно получить дополнительные награды.\n4, Обратите внимание: «Улучшенные хроники», разблокированные в данном событии, действуют только в рамках этого события. Просим Хранителей тайн подходить к покупкам обдуманно."
  },
  Activity_61369_ActivityName = {
    Text = "Нарастающая мелодия"
  },
  Activity_61369_ActivityPlot = {
    Text = "Страж может выбрать и пробудить одно из следующих лимитированных Колёс Судьбы!"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:Описание>\nЧёрный Омут полон непредсказуемых перемен, колёса судьбы вращаются вновь и вновь. Под звуки мелодии Гамельна бесконечные ритмы сливаются воедино, складываясь в колёса судьбы пройденного тобой пути. Пусть их поддержка сопровождает тебя до финальной ферматы.\n\n<Title:Правила события>\n·Во время события достаточно войти в игру один день, чтобы пробудить на выбор одно из 12 лимитированных колёс судьбы: «Гимн Божественного Короля», «Самое ценное сокровище», «Именем розы», «Преодолевая боль», «Тайное Ювенильный», «Заповедь Королевы», «Скрижаль божественного слова», «Пожирание уродливым телом», «Огромная Огромная сила благочестия», «Окончание стихотворной строки», «Милосердное вскармливание», «Время удачи»."
  },
  Activity_61369_BannerText = {
    Text = "Лимитированное Колесо Судьбы — получите бесплатно"
  },
  Activity_61370_ActivityName = {
    Text = "Серебряное сердце"
  },
  Activity_61370_ActivityPlot = {
    Text = "Входите ежедневно, чтобы получить памятное лимитированное SSR-колесо судьбы «Чистое серебряное сердце» — всего можно получить 16 штук!"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:Описание>\nКак бы ни рушился мир, пока каждый хранит изначальное, чистое серебряное сердце, история будет вновь и вновь повторяться, и новая жизнь возродится на опустошённой земле.\n\n<Title:Правила события>\n·Во время события Страж может ежедневно после входа в игру получить памятное лимитированное SSR-колесо судьбы «Чистое серебряное сердце» в разделе «Чистое серебряное сердце», всего до 16 раз.\n·Награды разблокируются последовательно в зависимости от накопленных дней входа. Ежедневная награда за Вход обновляется в 9:00 (GMT+8)."
  },
  Activity_61370_BannerText = {
    Text = "Лимитированное SSR-колесо судьбы бесплатно"
  },
  Activity_61371_ActivityName = {
    Text = "Желание шести крыльев"
  },
  Activity_61371_ActivityPlot = {
    Text = "В бурлящем хаосе Чёрного Омута серебряные ядра из бесконечных измерений просачиваются сквозь пространственные разломы и рассыпаются по берегам Омута. Тави бережно собирает их и складывает в уголке Чёрного Омута. Пусть эти серебряные ядра не способны остановить распространение Коррозии, но хранящиеся в них чувства и помыслы сияют вечным светом."
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:Описание>\nВ бурлящем хаосе Чёрного Омута серебряные ядра из бесконечных измерений просачиваются сквозь пространственные разломы и рассыпаются по берегам Омута. Тави бережно собирает их и складывает в уголке Чёрного Омута. Пусть эти серебряные ядра не способны остановить распространение Коррозии, но хранящиеся в них чувства и помыслы сияют вечным светом.\n\n<Title:Правила события>\n·Во время события Страж может ежедневно после входа в игру получить «Серебряные ядра» × 1000, всего до 6 раз.\n·Во время события, при накопленном входе 7 дней, Страж может напрямую получить лимитированное пробуждение текущего периода — «Тави»!\n·Награды разблокируются последовательно в зависимости от накопленных дней входа. Ежедневная награда за Вход обновляется в 9:00 (GMT+8)."
  },
  Activity_61371_BannerText = {
    Text = "Входите и получайте множество серебряных ядер"
  },
