  Activity_65387_ActivityName = {
    Text = "Извинения школьного кота"
  },
  Activity_65387_ActivityPlot = {
    Text = "В последнее время из-за уязвимостей в защитных мерах школы случаи вторжения Коррозии в виде <Del:«временных текстов и красных точек»> на территорию кампуса участились, причиняя множество неудобств учащимся. Поэтому администрация специально организовала несколько пунктов снабжения для раздачи припасов в качестве компенсации. (Учитывая ответственность за ошибки в управлении объектами, доставку всех припасов полностью взял на себя школьный кот.)"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:Описание>\nВ последнее время из-за уязвимостей в защитных мерах школы случаи вторжения Коррозии в виде <Del:«временных текстов и красных точек»> на территорию кампуса участились, причиняя множество неудобств учащимся. Поэтому администрация специально организовала несколько пунктов снабжения для раздачи припасов в качестве компенсации. (Учитывая ответственность за ошибки в управлении объектами, доставку всех припасов полностью взял на себя школьный кот.)\n\n<Title:Правила события>\n·Во время события Страж может ежедневно после входа в игру получить «Серебряные ядра» × 500 в разделе «Извинения школьного кота», всего до 5 раз.\n·Награды разблокируются последовательно в зависимости от накопленных дней входа. Ежедневная награда за Вход обновляется в 9:00 (GMT+8)."
  },
  Activity_65387_BannerText = {
    Text = "Входите и получайте серебряные ядра"
  },
  Activity_65502_ActivityName = {
    Text = "Нарастающая мелодия · Дуэт"
  },
  Activity_65502_ActivityPlot = {
    Text = "Страж может выбрать и пробудить одно из следующих лимитированных Колёс Судьбы!"
  },
  Activity_65502_ActivityTips = {
    Text = "<Title:Описание>\nЧёрный Омут полон непредсказуемых перемен, колёса судьбы вращаются вновь и вновь. Под звуки мелодии Гамельна бесконечные ритмы сливаются воедино, складываясь в колёса судьбы пройденного тобой пути. Пусть их поддержка сопровождает тебя до финальной ферматы.\n\n<Title:Правила события>\n·Во время события достаточно войти в игру один день, чтобы пробудить на выбор одно из 12 лимитированных колёс судьбы: «Гимн Божественного Короля», «Самое ценное сокровище», «Именем розы», «Преодолевая боль», «Тайное Ювенильный», «Заповедь Королевы», «Скрижаль божественного слова», «Пожирание уродливым телом», «Огромная Огромная сила благочестия», «Окончание стихотворной строки», «Милосердное вскармливание», «Время удачи»."
  },
  Activity_65502_BannerText = {
    Text = "Лимитированное Колесо Судьбы — получите бесплатно"
  },
  Activity_65521_ActivityName = {
    Text = "Набор снабжения для расследований"
  },
  Activity_65521_ActivityPlot = {
    Text = "Припасы для расследований от канцелярии Мессагера. Извлечены Алистером из плавающих обломков Чёрного Омута."
  },
