  Activity_66375_ActivityName = {
    Text = "Решающая битва: Изначальная Чёрная Чёрная Чёрная Чёрная тень"
  },
  Activity_66375_ActivityPlot = {
    Text = "Взгляд божества пронёсся через множество размерностей, и те, кто встретил его взгляд, были множеством серебряных фигур. \nОни малы, хрупки. Они сражаются, чтобы запомниться, до самой смерти."
  },
  Activity_66375_ActivityStageEndContent = {
    Text = "Мероприятие достигнуто, можно перейти к продолжению расследования."
  },
  Activity_66375_ActivityTips = {
    Text = "<Title: Против рока>\n· «Против рока» включает 7 уровней, которые невозможно Воссоздать, и позволяют напрямую бросить вызов Первоначальному зрению. В первый день акции откроются первые 3 уровня, затем каждые 3 дня будет открываться по одному уровню.\n· После победы над соответствующим Первоначальным зрением в каждом бою вы сможете получить соответствующую награду.\n· У каждого Первоначального зрения есть большое количество двойников. Каждый раз, когда любой Страж побеждает какой-либо тип Первоначального зрения, число оставшихся мировых копий этого типа в «Остатках мира» уменьшается на 1. Когда все двойники данного типа Первоначального зрения будут уничтожены, соответствующий Уровень закроется и его нельзя будет снова использовать для вызова.\n· Все Уровни находятся под влиянием «Р-прилив · Конец», но каждый Уровень предоставляет различные создания из «Чистого серебряного ядра», которые обеспечат вам мощные бонусы. Кроме того, каждый Уровень также предоставляет создание «Всевидящего глаза», которое даст Тави 120 единиц безумия в начале боя, а также повысит на 50% весь наносимый ею Урон, щиты и эффекты восстановления жизни.\n· Во всех уровнях необходимо выбрать помощника в бою. В течение всей акции каждый Страж с взаимным вниманием может предоставить вам помощь только один раз. Из-за использования помощи фактическое вознаграждение за Связать увеличится на 50% сверх базового вознаграждения.\n· Хранителю тайн нужно хотя бы завершить расследовательскую операцию 2-9, чтобы принять участие в этом событии.\n\n<Title: Расследовательская операция: Финальная глава>\n· Основное тело каждого типа Первоначального зрения всё ещë нужно победить самостоятельно в расследовательских операциях 9-5 до 9-11. Эти специальные Уровни не имеют достижений, звёзд, поддержки от создания «Всевидящего глаза», также нельзя использовать помощь союзника, и они более сложные.\n· После окончания акции «Против рока» можно будет разблокировать последующие Уровни «Расследовательской операции: Финальная глава». После совместного уничтожения всех двойников различных типов Первоначального зрения с другими Хранителями тайн можно заранее разблокировать соответствующие Уровни в расследовательских операциях 9-5 до 9-11."
  },
  Activity_66375_BannerText = {
    Text = "Особая активность доступна ограниченное время!"
  },
  Activity_66908_ActivityName = {
    Text = "Дыхание изобилия"
  },
  Activity_66908_ActivityTips = {
    Text = "<Title:Правила события>\n·Во время события «Дыхание изобилия» Страж может использовать системный предустановленный Отряд, включающий Тайис, для неограниченного прохождения указанных этапов.\n·Во время прохождения этапов события невозможно изменять Пробуждённых в отряде.\n<Title:Награды события>\n·После первого выполнения испытания этапа можно получить пробные награды в интерфейсе события."
  },
  Activity_67077_ActivityName = {
    Text = "Дар воспоминаний IX"
