  Activity_71982_ActivityName = {
    Text = "Дар резонанса душ"
  },
  Activity_71982_ActivityPlot = {
    Text = "Ты приходишь в кабинет директора, но обнаруживаешь, что внутри никого нет — похоже, то письмо было лишь чьей-то шуткой.\nКогда ты уже собираешься уйти, краем глаза замечаешь изящную подарочную коробку с запиской — «Моей возлюбленной/моему возлюбленному»."
