  Activity_71983_ActivityName = {
    Text = "Дар прозрения судьбы"
  },
  Activity_71983_ActivityPlot = {
    Text = "В тихой комнате раздаётся щёлканье. Когда ты подходишь проверить, распахнутое окно говорит о том, что «Незваный Гость» уже ушёл.\nТёплый солнечный Погоня за светом падает на появившуюся на столе подарочную коробку, изящная надпись переливается серебром — «Пусть Колесо Судьбы всегда будет благосклонна к тебе»."
