  Activity_73879_ActivityPlot = {
    Text = "Звёзды сошлись приближается, и шевеление плода в груди как барабан.\nКошмар тёмных ночей, который мучил её долгие годы, завершается сопровождаемый слезами бесчисленных последователей в момент финала.\nИз Его @1 Мрак @2, Великое Нисхождение @3 в мир."
