  Activity_81771_ActivityPlot = {
    Text = "Никто не видел священного сияния Царства бога, но из той случайно утекшей правды люди могут почувствовать Чёрная Чёрная тень Царства бога.\nОна была там, всё это время, и бесчисленные верующие сделают так, чтобы она действительно явилась.\nКакую бы тяжелую греховность не пришлось совершать за это."
