  Activity_90865_ActivityTips = {
    Text = "<Title: Зачатие бездны·Временные архивы>\n·В этом ограниченном путешествии содержится 8 наборов, из которых первый набор можно получить бесплатно, а для получения наборов со 2-го по 8-й необходимо купить «Зачатие бездны·Временные архивы».\n·После покупки «Зачатие бездны·Временные архивы» вы сможете сразу получить награду за 2-й набор; последующие наборы нужно будет ждать определенное время, прежде чем их можно будет получить.\n·При покупке «Зачатие бездны·Временные архивы» до 17 ноября 9:00 вы также получите дополнительные награды: эксклюзивный аватар «Элегия глубин», «Приглашение бесформенного» ×10! После 17 ноября 9:00 покупки не будут давать ограниченные эксклюзивные награды.\n·Покупка «Зачатие бездны·Временные архивы» ограничена по времени, по истечении срока покупки будет невозможно. Пожалуйста, Страж сделайте покупку до 15 декабря 9:00 по усмотрению."
